insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_eng2_v1'
from (values
('110.37.c.2.A',3,'A student reading a chemistry article meets the term ''covalent.'' Which resource gives the most reliable technical definition?','["a technical dictionary", "a movie review", "a travel guide", "a thesaurus of slang"]'::jsonb,0,'Technical dictionaries define specialized vocabulary.','original'),
('110.37.c.2.A',3,'Why would a reader check a glossary at the back of a nonfiction book?','["to count the pages", "to confirm the book''s own definitions of key terms", "to find the publisher''s address", "to see the next chapter"]'::jsonb,1,'Glossaries clarify specialized terms as used in the text.','original'),
('110.37.c.2.A',3,'An online dictionary entry lists an etymology. What does that information explain?','["the word''s rhyme", "the page where it appears", "the origin and history of a word", "the author''s opinion of it"]'::jsonb,2,'Etymology traces word origins.','original'),
('110.37.c.2.B',3,'A poem says ''the sun is a golden coin.'' What kind of meaning is ''coin'' here?','["denotative", "literal only", "technical", "figurative"]'::jsonb,3,'The sun is not literally a coin.','original'),
('110.37.c.2.B',3,'Which word carries the strongest negative connotation for a person who speaks a lot?','["blabbermouth", "chatty", "talkative", "communicative"]'::jsonb,0,'The informal compound sounds insulting.','original'),
('110.37.c.2.B',4,'In a novel, a character is called ''a fox.'' Using context about clever schemes, what does the word suggest?','["friendly", "cunning", "furry", "fast-moving only"]'::jsonb,1,'Figurative use draws on a fox''s reputation.','original'),
('110.37.c.2.C',3,'A critic praises a dancer''s ''pas de deux.'' What does the phrase refer to?','["a costume", "a solo dance", "a dance for two performers", "a stage curtain"]'::jsonb,2,'French for ''step of two.''','original'),
('110.37.c.2.C',3,'What does the phrase ''savoir faire'' suggest about a person?','["lack of training", "a love of travel", "great wealth", "skill at handling social situations gracefully"]'::jsonb,3,'French for ''to know how to do.''','original'),
('110.37.c.2.C',4,'A speech mentions ''quid pro quo.'' What is described?','["an exchange of one thing for another", "a secret code", "a free gift", "a legal appeal"]'::jsonb,0,'Latin for ''something for something.''','original'),
('110.37.c.4.F',3,'Passage: ''Kofi folded the letter into smaller and smaller squares, then slipped it, unread, into his coat.'' What can be inferred?','["he is eager to read it aloud", "he is nervous or afraid of what the letter says", "he is bored by mail", "he has forgotten the letter"]'::jsonb,1,'Folding and hiding suggest dread.','original'),
('110.37.c.4.F',3,'Passage: ''The market stalls were packed, yet the vendor lowered his voice whenever the soldiers passed.'' What is the best inference?','["he is selling to the soldiers", "the market is closed", "he feels cautious or threatened around the soldiers", "he enjoys the soldiers'' company"]'::jsonb,2,'Lowering his voice implies fear.','original'),
('110.37.c.4.F',4,'Which statement is the best example of using evidence to support an inference?','["''Many people yawn.''", "''She is a person.''", "''I just feel she is tired.''", "''She seems exhausted, since she yawned through every scene.''"]'::jsonb,3,'A sound inference cites text details.','original'),
('110.37.c.4.G',3,'When deciding on a text''s key idea, a reader should do what with the details?','["judge which ones matter most to the central point", "ignore all of them", "count how many there are", "treat every detail as equally important"]'::jsonb,0,'Key ideas come from weighing details.','original'),
('110.37.c.4.G',3,'A paragraph gives three examples of ocean pollution and one aside about a boat race. Which detail is least important to the key idea?','["the third pollution example", "the aside about the boat race", "the second pollution example", "the first pollution example"]'::jsonb,1,'The aside is off-topic.','original'),
('110.37.c.4.G',4,'An article''s last paragraph restates its main claim. Why is that detail helpful to a reader?','["it introduces a new topic", "it lists sources", "it confirms the key idea", "it hides the key idea"]'::jsonb,2,'Conclusions often reinforce main ideas.','original'),
('110.37.c.4.H',3,'One article says a river''s flow dropped after a dam; another says fish numbers fell downstream. What new understanding could a reader create?','["rivers never change", "fish prefer dams", "the articles contradict each other entirely", "the dam may have harmed fish by reducing flow"]'::jsonb,3,'Synthesis links ideas across texts.','original'),
('110.37.c.4.H',3,'Which action best shows synthesizing two texts?','["combining their ideas into a new conclusion", "memorizing both", "reading only the longer one", "copying the first one"]'::jsonb,0,'Synthesis creates new understanding.','original'),
('110.37.c.4.I',2,'A reader realizes she cannot explain what she just read. What is the best strategy?','["skip to the last page", "re-read the section slowly and ask questions", "stop reading for good", "keep going without thinking"]'::jsonb,1,'Monitoring comprehension calls for adjustment.','original'),
('110.37.c.4.I',3,'Which fix-up strategy uses what the reader already knows?','["reading faster", "covering the page", "using background knowledge to understand a confusing passage", "ignoring unfamiliar words"]'::jsonb,2,'Prior knowledge aids comprehension.','original'),
('110.37.c.5.B',3,'A student writes a response comparing how two poems treat the idea of time. This response shows what?','["a summary of one poem only", "a personal diary entry", "a spelling mistake", "understanding across texts"]'::jsonb,3,'Comparing texts shows understanding.','original'),
('110.37.c.5.B',3,'Which sentence best begins a comparison between two characters?','["''Both characters face betrayal, but they respond in opposite ways.''", "''Betrayal is a word.''", "''The book has chapters.''", "''I like characters.''"]'::jsonb,0,'A comparison names similarity and difference.','original'),
('110.37.c.5.C',3,'In an interpretive response, what combination is strongest?','["commentary alone with no text", "a quotation followed by the writer''s own commentary", "a quotation alone", "a list of plot points"]'::jsonb,1,'Evidence plus commentary supports interpretation.','original'),
('110.37.c.5.C',3,'A student quotes a line, then writes, ''This shows the narrator''s guilt because...'' What is the second part called?','["a thesis", "a transition only", "commentary", "a citation"]'::jsonb,2,'Commentary explains the evidence.','original'),
('110.37.c.5.C',4,'Which is the weakest use of text evidence in an interpretive paragraph?','["linking the quotation to the thesis", "choosing a quotation that fits the claim", "introducing the quotation, then explaining it", "dropping a quotation in with no explanation"]'::jsonb,3,'Evidence needs explanation.','original'),
('110.37.c.5.D',3,'A good paraphrase of a sentence should do what?','["keep the meaning while using different words", "change the meaning", "add the writer''s opinion", "copy the exact words"]'::jsonb,0,'Paraphrase restates in your own words.','original'),
('110.37.c.5.D',3,'A summary of a long story should include what?','["the reader''s feelings only", "the main events in logical order", "every minor detail", "only the ending"]'::jsonb,1,'Summaries are concise and ordered.','original'),
('110.37.c.5.D',4,'Which sentence is a summary rather than a paraphrase of a whole chapter?','["''I felt sad.''", "''The first sentence says it was dry.''", "''The chapter traces the family''s journey from drought to a new home.''", "''The chapter has thirty pages.''"]'::jsonb,2,'Summaries condense the whole.','original'),
('110.37.c.5.F',3,'Which is an academic vocabulary word suited to a formal response?','["whatever", "show off", "kinda", "demonstrate"]'::jsonb,3,'Formal writing uses academic terms.','original'),
('110.37.c.5.F',3,'A student studying the French Revolution should use which term for rule by one all-powerful leader?','["autocracy", "banquet", "festival", "picnic"]'::jsonb,0,'Content vocabulary helps precision.','original'),
('110.37.c.5.G',3,'An implicit meaning in a text is one that is what?','["found in the footnotes", "suggested but not stated", "the same as the title", "spelled out"]'::jsonb,1,'Implicit meaning must be inferred.','original'),
('110.37.c.5.G',4,'A narrator says, ''The old clock ticked on, though no one in the house listened anymore.'' What implicit meaning is likely?','["the narrator is a clockmaker", "the clock is broken", "the house has become lonely or abandoned", "everyone is asleep happily"]'::jsonb,2,'Details imply emptiness.','original'),
('110.37.c.5.J',3,'An author claims that every city needs a public library but offers only the opinion that books are nice. What is the best challenge?','["the author is too famous", "the essay has a title", "the claim uses long words", "the evidence is too weak to support the claim"]'::jsonb,3,'A claim needs relevant evidence.','original'),
('110.37.c.5.J',4,'To defend an author''s claim, a reader should do what?','["point to specific supporting evidence in the text", "attack the author", "state a personal opinion with no proof", "ignore the text"]'::jsonb,0,'Defending requires text evidence.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_eng2_v1'
from (values
('110.37.c.6.A',3,'In a story, a proud ruler loses everything because he refuses advice. Which theme is developed through his plot?','["loss is meaningless", "pride can lead to downfall", "rulers never fail", "advice is always wrong"]'::jsonb,1,'Plot consequences reveal theme.','original'),
('110.37.c.6.A',4,'Two stories show characters who sacrifice for family. How can a reader compare their themes?','["by counting pages", "by ignoring the endings", "by noting how each plot and character shows the value of family", "by comparing the titles"]'::jsonb,2,'Compare how characters and plots develop ideas.','original'),
('110.37.c.6.A',3,'A character who starts out selfish becomes generous after a crisis. This change most directly develops what?','["the rhyme scheme", "the title page", "the setting''s name", "the theme"]'::jsonb,3,'Character change builds theme.','original'),
('110.37.c.6.B',3,'A wise old mentor who guides the hero is an example of which kind of figure?','["an archetype", "a stanza", "a glossary entry", "a footnote"]'::jsonb,0,'Archetypes recur across cultures.','original'),
('110.37.c.6.B',4,'Which technique makes a character feel believable rather than flat?','["making them identical to others", "giving the character both strengths and flaws", "making them perfect", "giving them no motives"]'::jsonb,1,'Believable characters are complex.','original'),
('110.37.c.6.B',3,'A character born in a poor village in a strict era makes choices shaped by limited options. What shapes the character here?','["the rhyme scheme", "the page count", "historical and cultural context", "the font"]'::jsonb,2,'Context influences characterization.','original'),
('110.37.c.6.C',3,'Why might an author include a brief scene of a character''s act of kindness before the climax?','["to avoid conflict", "to change the genre", "to delay the title", "to build sympathy that raises the stakes"]'::jsonb,3,'Isolated scenes contribute to the whole plot.','original'),
('110.37.c.6.C',4,'If a single scene is removed and the rest of the plot no longer makes sense, what does that show?','["the scene is essential to the plot", "the author made a spelling error", "the plot has no theme", "the scene is decoration"]'::jsonb,0,'Essential scenes carry the plot.','original'),
('110.37.c.6.D',3,'A play set in a society that forbids certain marriages creates conflict. How does the cultural setting influence the plot?','["it ends the story", "it creates obstacles for the characters", "it hides the characters", "it removes conflict"]'::jsonb,1,'Setting shapes conflict.','original'),
('110.37.c.6.D',4,'A story from ancient Greece centers on fate. How does the historical culture influence the theme?','["culture has no effect", "the setting is only a backdrop", "beliefs about fate shape what the characters believe they can change", "fate is never mentioned"]'::jsonb,2,'Cultural beliefs drive theme.','original'),
('110.37.c.7.A',3,'Which epic from ancient Mesopotamia follows a king''s search for immortality?','["Beowulf", "The Aeneid", "The Odyssey", "The Epic of Gilgamesh"]'::jsonb,3,'One of the oldest known works of literature.','original'),
('110.37.c.7.A',3,'Which author wrote the novel ''Don Quixote''?','["Miguel de Cervantes", "Leo Tolstoy", "Gabriel García Márquez", "Albert Camus"]'::jsonb,0,'A foundational Spanish novel.','original'),
('110.37.c.7.A',3,'Which Russian author wrote ''Crime and Punishment''?','["Maxim Gorky", "Fyodor Dostoevsky", "Anton Chekhov", "Boris Pasternak"]'::jsonb,1,'A major nineteenth-century novel.','original'),
('110.37.c.7.A',4,'Which work by Sophocles features a king who unknowingly fulfills a prophecy?','["Medea", "Antigone", "Oedipus Rex", "The Frogs"]'::jsonb,2,'A classic tragedy of fate.','original'),
('110.37.c.7.A',3,'Which 20th-century French author wrote ''The Stranger''?','["Jules Verne", "Victor Hugo", "Molière", "Albert Camus"]'::jsonb,3,'A key work of existentialism.','original'),
('110.37.c.7.B',3,'Rhyme that occurs within a single line of poetry is called what?','["internal rhyme", "slant rhyme", "eye rhyme", "end rhyme"]'::jsonb,0,'Internal rhyme sits inside a line.','original'),
('110.37.c.7.B',4,'Words that look like they should rhyme but do not, such as ''love'' and ''move,'' are an example of what?','["perfect rhyme", "eye rhyme", "internal rhyme", "end rhyme"]'::jsonb,1,'They match in spelling, not sound.','original'),
('110.37.c.7.B',4,'Words with similar but not identical sounds, such as ''worm'' and ''warm,'' form what?','["internal rhyme", "eye rhyme", "slant rhyme", "perfect rhyme"]'::jsonb,2,'Slant rhyme is near rhyme.','original'),
('110.37.c.7.B',3,'The pattern of stressed and unstressed syllables in a line of poetry is its what?','["plot", "setting", "tone", "meter"]'::jsonb,3,'Meter is the rhythmic pattern.','original'),
('110.37.c.7.B',3,'A repeated line or phrase at intervals in a poem is called what?','["a refrain", "a stage direction", "an index", "a footnote"]'::jsonb,0,'Refrains echo through a poem.','original'),
('110.37.c.7.C',3,'A work that uses humor and exaggeration to criticize society is called what?','["an epic", "satire", "an elegy", "a memoir"]'::jsonb,1,'Satire critiques through wit.','original'),
('110.37.c.7.C',3,'A dramatic aside is spoken by a character to do what?','["end the scene", "introduce the setting", "share a remark with the audience unheard by the others", "address the director"]'::jsonb,2,'Asides reveal private thoughts.','original'),
('110.37.c.7.C',4,'The audience knows a character is about to be betrayed; the character does not. This is which convention?','["a prologue", "soliloquy", "foreshadowing only", "dramatic irony"]'::jsonb,3,'Audience awareness creates tension.','original'),
('110.37.c.7.D.i',3,'Which sentence is the clearest thesis for an essay on a novel''s theme?','["''In the novel, the author shows that isolation weakens people by tracing the narrator''s decline.''", "''Authors write about things.''", "''The novel is long.''", "''I read a novel.''"]'::jsonb,0,'A thesis states a clear claim.','original'),
('110.37.c.7.D.i',3,'What should the conclusion of an expository essay do?','["list unrelated facts", "restate the thesis and leave a final thought", "introduce a new argument", "repeat the introduction word for word"]'::jsonb,1,'Conclusions close the argument.','original'),
('110.37.c.7.D.ii',3,'How does an essay''s organizational design relate to its thesis?','["the thesis follows the structure''s length", "the structure is unrelated", "the structure should support and develop the thesis", "design replaces the thesis"]'::jsonb,2,'Structure serves the main claim.','original'),
('110.37.c.7.D.ii',4,'A thesis argues that two empires differed in how they governed. Which design fits best?','["a list of rhymes", "alphabetical order", "a timeline of unrelated events", "compare and contrast"]'::jsonb,3,'Comparison suits a thesis of difference.','original'),
('110.37.c.7.E.i',3,'Which is a clear arguable claim?','["''Schools should start later to improve student performance.''", "''Schools exist.''", "''Mornings are early.''", "''Students attend school.''"]'::jsonb,0,'An arguable claim can be debated.','original'),
('110.37.c.7.E.i',3,'An appeal to emotion is called what?','["logos", "pathos", "ethos", "syntax"]'::jsonb,1,'Pathos moves feelings.','original'),
('110.37.c.7.E.i',3,'An appeal that builds the writer''s credibility is called what?','["irony", "logos", "ethos", "pathos"]'::jsonb,2,'Ethos establishes trustworthiness.','original'),
('110.37.c.7.E.ii',4,'A writer says, ''Critics argue the plan is costly; however, savings over ten years outweigh the cost.'' What is the second half?','["a title", "a concession", "a thesis", "a rebuttal"]'::jsonb,3,'It answers the objection.','original'),
('110.37.c.7.E.ii',3,'Which is a type of strong evidence in an argument?','["statistics from a reliable study", "an unnamed friend''s guess", "a rumor", "a slogan"]'::jsonb,0,'Credible data supports claims.','original'),
('110.37.c.7.E.iii',3,'Which choice best shows awareness of an audience of skeptical readers?','["using only slang", "addressing their likely objections", "insulting their views", "ignoring them"]'::jsonb,1,'Audience awareness shapes the argument.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_eng2_v1'
from (values
('110.37.c.7.E.iii',3,'A letter to a mayor asking for a new crosswalk should use what tone?','["joking", "careless", "polite and persuasive", "rude"]'::jsonb,2,'Tone matches the audience.','original'),
('110.37.c.7.F',3,'What is the purpose of captions in a digital article?','["to list sources only", "to replace the article", "to hide the images", "to explain or add context to images"]'::jsonb,3,'Captions clarify visuals.','original'),
('110.37.c.7.F',3,'A podcast with a transcript and episode notes is an example of what?','["a multimodal text", "a single-mode text", "a poem", "a footnote"]'::jsonb,0,'It combines audio and text.','original'),
('110.37.c.8.A',3,'A pamphlet shows a cheerful family and urges readers to get vaccinated. What is the author''s purpose?','["to confuse", "to persuade", "to entertain", "to mock"]'::jsonb,1,'It urges action.','original'),
('110.37.c.8.A',4,'An op-ed uses technical economic terms and charts. Who is the likely audience?','["readers who dislike data", "no one", "readers familiar with economics", "young children"]'::jsonb,2,'Language signals audience.','original'),
('110.37.c.8.A',3,'The central message of a fable is usually called what?','["its index", "its footnote", "its glossary", "its moral"]'::jsonb,3,'Fables convey morals.','original'),
('110.37.c.8.B',3,'An essay describes how the printing press changed society step by step over time. What text structure is used?','["chronological sequence", "spatial order", "compare and contrast", "problem and solution"]'::jsonb,0,'It follows time order.','original'),
('110.37.c.8.B',3,'A text presents a shortage of clean water and then lists proposed fixes. What structure is it?','["description", "problem and solution", "classification", "sequence"]'::jsonb,1,'It poses a problem then answers it.','original'),
('110.37.c.8.B',4,'Why might an author choose cause-and-effect structure?','["to describe a place only", "to avoid facts", "to show how one event leads to another", "to list opinions"]'::jsonb,2,'Structure supports purpose.','original'),
('110.37.c.8.C',3,'A sidebar in a textbook mostly serves to do what?','["hide the main text", "end the chapter", "replace the index", "provide extra related information"]'::jsonb,3,'Sidebars supplement.','original'),
('110.37.c.8.C',3,'A timeline graphic in a history article helps readers see what?','["the order and spacing of events", "the cost of the book", "the author''s age", "rhyming words"]'::jsonb,0,'Timelines show sequence.','original'),
('110.37.c.8.C',4,'A pie chart is best used to show what?','["a poem''s meter", "parts of a whole", "a map route", "change over time"]'::jsonb,1,'Pie charts show proportions.','original'),
('110.37.c.8.D',3,'An author describes a prison as ''a stone mouth that never closed.'' How does this language shape perception?','["it makes it seem cozy", "it makes it seem new", "it makes the prison seem threatening and consuming", "it has no effect"]'::jsonb,2,'Figurative language influences views.','original'),
('110.37.c.8.D',4,'A writer repeatedly uses the word ''swarm'' for a crowd of protesters. What perception is likely?','["that the crowd is small", "that the crowd is silent", "that the crowd is orderly", "that the crowd is chaotic and menacing"]'::jsonb,3,'Word choice slants perception.','original'),
('110.37.c.8.E',3,'A character who says ''Great job'' after a terrible performance is using what?','["sarcasm", "a refrain", "an allegory", "foreshadowing"]'::jsonb,0,'Sarcasm means the opposite, with a sting.','original'),
('110.37.c.8.E',3,'A recurring image of a locked door across a novel is an example of what?','["a stanza", "a motif", "a plot twist only", "an index"]'::jsonb,1,'Motifs repeat meaningful elements.','original'),
('110.37.c.8.E',3,'A bank robber is arrested after calling the police to report a missing wallet. What kind of irony is this?','["sarcasm", "dramatic irony", "situational irony", "verbal irony"]'::jsonb,2,'The outcome defies expectation.','original'),
('110.37.c.8.F',3,'An author uses ornate vocabulary and long sentences in a ceremonial speech. What tone results?','["playful", "casual", "hurried", "formal and grand"]'::jsonb,3,'Diction and syntax shape tone.','original'),
('110.37.c.8.F',4,'A narrator''s voice uses slang, fragments and humor. What does this diction create?','["an informal, personal voice", "a formal lecture", "a scientific report", "a legal contract"]'::jsonb,0,'Voice reflects diction.','original'),
('110.37.c.8.F',3,'Which choice of syntax most clearly creates a rushed, anxious mood?','["long flowing clauses", "short, clipped sentences", "formal address", "a calm list"]'::jsonb,1,'Short sentences quicken pace.','original'),
('110.37.c.8.G',3,'''It was the best of ideas, it was the worst of ideas'' uses which device?','["parallelism only", "alliteration", "antithesis", "onomatopoeia"]'::jsonb,2,'Opposites are set against each other.','original'),
('110.37.c.8.G',3,'Repeating the same sentence structure to link ideas is called what?','["irony", "hyperbole", "antithesis", "parallelism"]'::jsonb,3,'Parallel structure creates rhythm.','original'),
('110.37.c.8.G',4,'A speaker moves from sorrow to hope midway through a speech. What is this rhetorical shift used to do?','["to mark a change in tone and lift the audience", "to repeat the introduction", "to confuse the audience", "to end the speech"]'::jsonb,0,'Shifts guide emotion.','original'),
('110.37.c.9.B.i',3,'An essay on three causes of an event should be organized in what way?','["only a list of effects", "one paragraph for each cause with clear transitions", "one giant paragraph", "random order"]'::jsonb,1,'Organization matches purpose.','original'),
('110.37.c.9.B.ii',3,'Which detail best supports the idea that a character is brave?','["she lives nearby", "she is a person", "she ran back into the burning shop to pull out a trapped neighbor", "she owns a coat"]'::jsonb,2,'Specific details show depth.','original'),
('110.37.c.9.B.ii',3,'What does a writer''s commentary add to an example?','["a new topic", "a citation style", "extra length only", "explanation of why the example matters"]'::jsonb,3,'Commentary shows thinking.','original'),
('110.37.c.9.C',3,'A writer replaces the vague word ''thing'' with ''treaty.'' What is improved?','["diction", "page numbers", "margins", "capitalization"]'::jsonb,0,'Precise words improve clarity.','original'),
('110.37.c.9.C',3,'Cutting a paragraph that wanders off topic improves what?','["title font", "development and focus", "page color", "spelling"]'::jsonb,1,'Revision strengthens focus.','original'),
('110.37.c.9.C',4,'Combining short sentences with conjunctions and varying their openings improves what?','["thesis statement", "citation format", "sentence effectiveness and style", "the title"]'::jsonb,2,'Sentence variety improves flow.','original'),
('110.37.c.9.D.ii',3,'Which sentence uses the active voice?','["The plan has been approved.", "The plan was approved by the committee.", "The plan is being approved.", "The committee approved the plan."]'::jsonb,3,'The subject performs the action.','original'),
('110.37.c.9.D.ii',4,'When is the passive voice most appropriate?','["when the actor is unknown or unimportant", "never", "in every sentence", "always"]'::jsonb,0,'Passive voice focuses on the receiver.','original'),
('110.37.c.9.D.iv',3,'In ''we toured lake victoria and then flew to nairobi in august,'' which words need capital letters?','["victoria and nairobi only", "we, lake, victoria, nairobi and august", "toured, flew and august", "we and august only"]'::jsonb,1,'Capitalize the first word, proper names of places and the names of months.','original'),
('110.37.c.10.D',3,'Which line is the best opening for a professional email asking a teacher for a recommendation letter?','["''Hey, got a minute?''", "''Sup.''", "''Dear Ms. Alvarez, I am writing to ask whether you would be willing to write a recommendation for me.''", "''Yo teacher, write me a letter.''"]'::jsonb,2,'Professional correspondence is polite and clear.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_eng2_v1'
from (values
('110.37.c.10.D',3,'A friendly letter to a pen pal can differ from a business letter by being what?','["required to have a thesis", "written without words", "signed by a lawyer", "more casual in tone"]'::jsonb,3,'Friendly letters allow casual tone.','original'),
('110.37.c.11.E',3,'Which of these is the best first step for finding reliable sources on a research topic?','["searching a library database or reputable site", "reading comments on a video", "asking a friend only", "guessing"]'::jsonb,0,'Reliable databases give vetted sources.','original'),
('110.37.c.11.F',3,'A researcher combines facts from four sources into one summary and credits each. What is this called?','["plagiarism", "synthesis", "outlining only", "copying"]'::jsonb,1,'Synthesis blends and credits.','original'),
('110.37.c.11.H',3,'Which practice shows ethical use of source material?','["claiming the idea as one''s own", "pasting without credit", "quoting with quotation marks and citing the source", "changing a few words and omitting the source"]'::jsonb,2,'Ethical writers cite sources.','original'),
('110.37.c.11.G.i',3,'A website sells a product and publishes only glowing ''studies'' that list no authors. What should a researcher conclude?','["the source is peer reviewed", "the source is a government report", "the source is perfectly neutral", "the source may be biased and not credible"]'::jsonb,3,'Missing authors and selective evidence signal bias.','original'),
('110.37.c.11.G.i',4,'What does ''bias by omission'' mean?','["leaving out important facts that don''t fit the author''s view", "using long sentences", "listing too many facts", "citing too many sources"]'::jsonb,0,'Omission skews the picture.','original'),
('110.37.c.11.G.ii',3,'''Either we ban all cars or the planet will be destroyed.'' What fallacy is this?','["hasty generalization", "either-or (false dilemma)", "ad hominem", "bandwagon"]'::jsonb,1,'It ignores middle options.','original'),
('110.37.c.11.G.ii',3,'A writer meets two rude waiters and concludes, ''Everyone in the city is rude.'' What fallacy is this?','["straw man", "slippery slope", "hasty generalization", "circular reasoning"]'::jsonb,2,'Two cases cannot represent a city.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'English Language Arts and Reading' and d.language = 'en'
